pub struct Handle {              // public type, private representation
    inner: Inner,                // not nameable outside this crate
}

pub(crate) struct Inner { state: u64 }   // crate-internal detail

impl Handle {
    pub fn new() -> Self { Self { inner: Inner { state: 0 } } }
    pub fn step(&mut self) { self.inner.state += 1; }
}

